import { it } from "vitest";
import prettier from "prettier";

// prettier-ignore
const cases = [{"path":"e2e/c006-evidence-reporter.ts","contents":"import { createHash } from \"node:crypto\";\nimport { existsSync, readFileSync, readdirSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport type {\n  FullResult,\n  Reporter,\n  TestCase,\n  TestResult,\n} from \"@playwright/test/reporter\";\n\nconst evidenceDir = join(process.cwd(), \"test-results\", \"c006-evidence\");\n\nfunction candidateHead() {\n  try {\n    if (!process.env.GITHUB_EVENT_PATH) return undefined;\n    const event = JSON.parse(\n      readFileSync(process.env.GITHUB_EVENT_PATH, \"utf8\"),\n    );\n    return event.pull_request?.head?.sha as string | undefined;\n  } catch {\n    return undefined;\n  }\n}\n\ntype TraceFile = { name: string; path: string };\n\nexport default class C006EvidenceReporter implements Reporter {\n  private traces: TraceFile[] = [];\n\n  onTestEnd(test: TestCase, result: TestResult) {\n    const mode = [\"split\", \"direct\", \"scaling\", \"r\", \"nxr_first\", \"nxr_second\"].find(\n      (candidate) => test.title.startsWith(`${candidate}:`),\n    );\n    const name = mode ? `pc-${mode}` : null;\n    if (!name || this.traces.some((item) => item.name === name)) return;\n    const trace = result.attachments.find(\n      (item) => item.path && item.name === \"trace\" && existsSync(item.path),\n    );\n    if (trace?.path) this.traces.push({ name, path: trace.path });\n  }\n\n  onEnd(result: FullResult) {\n    console.log(\n      \"C006_BROWSER_EXECUTION:\" +\n        JSON.stringify({\n          runId: process.env.GITHUB_RUN_ID ?? \"local\",\n          head: candidateHead() ?? process.env.GITHUB_SHA ?? \"local\",\n          checkoutSha: process.env.GITHUB_SHA ?? \"local\",\n          status: result.status,\n          os: process.platform,\n          node: process.version,\n          playwright: \"1.56.1\",\n          seed: 0,\n          browserKind: \"Linux Chromium, CSS viewport emulation only\",\n        }),\n    );\n\n    if (!process.env.CI) return;\n    const files: TraceFile[] = existsSync(evidenceDir)\n      ? readdirSync(evidenceDir)\n          .filter((file) => file.endsWith(\".png\"))\n          .sort()\n          .map((file) => ({\n            name: file,\n            path: join(evidenceDir, file),\n          }))\n      : [];\n    for (const trace of this.traces)\n      files.push({\n        name: `${trace.name}-trace.zip`,\n        path: trace.path,\n      });\n    console.log(\n      \"C006_EVIDENCE_INDEX:\" + JSON.stringify(files.map((item) => item.name)),\n    );\n    for (const item of files) {\n      const bytes = readFileSync(item.path);\n      const sha = createHash(\"sha256\").update(bytes).digest(\"hex\");\n      console.log(\n        \"C006_EVIDENCE_META:\" +\n          JSON.stringify({\n            name: item.name,\n            sha256: sha,\n            bytes: bytes.length,\n          }),\n      );\n      if (bytes.length > 4_500_000) {\n        console.log(\"C006_TOO_LARGE:\" + item.name);\n        continue;\n      }\n      const base64 = bytes.toString(\"base64\");\n      if (item.name.endsWith(\".zip\")) {\n        const chunkSize = 48_000;\n        const total = Math.ceil(base64.length / chunkSize);\n        console.log(\n          \"C006_TRACE_INDEX:\" +\n            JSON.stringify({ name: item.name, sha256: sha, total }),\n        );\n        for (let i = 0; i < total; i += 1)\n          console.log(\n            `C006_TRACE_CHUNK:${item.name}:${i}:${base64.slice(i * chunkSize, (i + 1) * chunkSize)}`,\n          );\n      } else {\n        console.log(`C006_PNG:${item.name}:${sha}:${base64}`);\n      }\n    }\n  }\n}\n"},{"path":"e2e/c007-scaling.spec.ts","contents":"import { test, expect, type Page, type TestInfo } from \"@playwright/test\";\nimport { mkdirSync } from \"node:fs\";\nimport { join } from \"node:path\";\n\nasync function capture(page: Page, info: TestInfo, name: string) {\n  const dir = join(process.cwd(), \"test-results\", \"c006-evidence\");\n  mkdirSync(dir, { recursive: true });\n  const path = join(dir, name);\n  await page.screenshot({ path, fullPage: true, animations: \"disabled\" });\n  await info.attach(name, { path, contentType: \"image/png\" });\n}\nfunction parseProblem(prompt: string) {\n  const found = prompt.match(/^(\\d+)\\s*÷\\s*(\\d+)$/);\n  if (!found) throw new Error(\"Scaling pilot prompt not supported: \" + prompt);\n  return { a: Number(found[1]), b: Number(found[2]) };\n}\nasync function firstStep(page: Page, rough = false) {\n  const question = (await page.locator('[aria-label=\"C2训练作答\"] h2').innerText()).trim();\n  const { a, b } = parseProblem(question);\n  const b0 = rough ? b - 1 : b + 1;\n  await page.getByLabel(\"自选基准 B0\").fill(String(b0));\n  await page.getByLabel(\"带符号 Δ = B0 − B\").fill(rough ? \"-1\" : \"1\");\n  if (rough) {\n    await page.getByRole(\"radio\", { name: /粗商×Δ/ }).check();\n    // Branch reset is deliberate: re-enter the actual user choices.\n    await page.getByLabel(\"自选基准 B0\").fill(String(b0));\n    await page.getByLabel(\"带符号 Δ = B0 − B\").fill(\"-1\");\n    const qrough = Number((a / b).toFixed(1));\n    const c1 = -qrough;\n    const a1 = a + c1;\n    const q1 = a1 / b0;\n    await page.getByLabel(\"自然粗商 q粗\").fill(String(qrough));\n    await page.getByLabel(\"一阶带符号修正 C1\").fill(String(c1));\n    await page.getByLabel(\"一阶分子 A1\").fill(String(a1));\n    await page.getByLabel(\"一阶结果 Q1\").fill(String(q1));\n    await page.getByLabel(\"最终实际商\").fill(String(q1));\n    await expect(page.getByLabel(\"实际基准商 Q0\")).toHaveCount(0);\n    await expect(page.getByLabel(\"实际近似幅度 r（小数）\")).toHaveCount(0);\n  } else {\n    const q0 = a / b0;\n    await page.getByLabel(\"实际基准商 Q0\").fill(String(q0));\n    await page.getByLabel(\"最终实际商\").fill(String(q0));\n    await expect(page.getByLabel(\"实际近似幅度 r（小数）\")).toHaveCount(0);\n  }\n}\nconst viewports = [\n  { name: \"pc\", width: 1440, height: 900 },\n  { name: \"pad\", width: 768, height: 1024 },\n  { name: \"mobile\", width: 390, height: 844 },\n] as const;\n\nfor (const vp of viewports) {\n  test(`scaling: ${vp.name} ${vp.width}x${vp.height} ten real zero-order answers and rough path`, async ({ page }, info) => {\n    await page.setViewportSize({ width: vp.width, height: vp.height });\n    await page.addInitScript(() => { Math.random = () => 0; });\n    const errors: string[] = [];\n    page.on(\"pageerror\", e => errors.push(e.message));\n    await page.goto(\"/c2-lab\");\n    await expect(page.getByRole(\"button\", { name: /补偿放缩 Scaling.*10题/ })).toBeVisible();\n    await capture(page, info, `scaling-${vp.name}-entry.png`);\n    await page.getByRole(\"button\", { name: /补偿放缩 Scaling.*10题/ }).click();\n    const invalid = async () => {\n      await page.getByLabel(\"自选基准 B0\").fill(\"0x10\");\n      await page.getByLabel(\"带符号 Δ = B0 − B\").fill(\"1\");\n      await page.getByLabel(\"实际基准商 Q0\").fill(\"1\");\n      await page.getByLabel(\"最终实际商\").fill(\"1\");\n      await page.getByRole(\"button\", { name: \"提交本题\" }).click();\n      await expect(page.locator('[aria-label=\"C2训练作答\"] [role=\"alert\"]')).toBeVisible();\n      await expect(page.getByText(\"第 1 / 10 题\")).toBeVisible();\n      await capture(page, info, `scaling-${vp.name}-invalid.png`);\n    };\n    await invalid();\n    for(let index=0;index<10;index++){\n      await expect(page.getByText(`第 ${index+1} / 10 题`)).toBeVisible();\n      await firstStep(page);\n      if(index===0) await capture(page,info,`scaling-${vp.name}-zero.png`);\n      await page.getByRole(\"button\", { name: \"提交本题\" }).click();\n    }\n    await expect(page.getByRole(\"heading\", { name: \"答对 10 / 10 题\" })).toBeVisible();\n    await capture(page,info,`scaling-${vp.name}-results.png`);\n    await page.getByRole(\"button\", { name: \"再练一组\" }).click();\n    await expect(page.getByText(\"第 1 / 10 题\")).toBeVisible();\n    await capture(page,info,`scaling-${vp.name}-retry.png`);\n    await firstStep(page, true);\n    await capture(page,info,`scaling-${vp.name}-rough.png`);\n    await page.getByRole(\"button\", { name: \"提交本题\" }).click();\n    await expect(page.getByText(\"第 2 / 10 题\")).toBeVisible();\n    expect(errors).toEqual([]);\n    const metrics = await page.evaluate(() => ({\n      pageWidth: document.documentElement.scrollWidth,\n      viewport: window.innerWidth,\n    }));\n    expect(metrics.pageWidth).toBeLessThanOrEqual(metrics.viewport+1);\n  });\n}\n"},{"path":"src/components/C2PilotTraining.tsx","contents":"\"use client\";\n\nimport { useState, type FormEvent } from \"react\";\nimport type { TrainingResponse } from \"@/lib/types\";\nimport {\n  c2PilotScore,\n  createC2PilotSession,\n  submitC2PilotAnswer,\n  type C2PilotMode,\n  type C2PilotSession,\n} from \"@/lib/c2/pilot-session\";\nimport { c2DirectCompose } from \"@/lib/c2/direct-pilot\";\nimport { C2ScalingFields, emptyScalingForm, scalingResponseFields } from \"./C2ScalingFields\";\nimport styles from \"./C2PilotTraining.module.css\";\n\nconst options: { mode: C2PilotMode; label: string; detail: string }[] = [\n  {\n    mode: \"scaling\",\n    label: \"补偿放缩 Scaling\",\n    detail: \"10题 · 自选基准 · 实际补偿路径\",\n  },\n  {\n    mode: \"split\",\n    label: \"拆分 Split\",\n    detail: \"10题 · 带符号比例块与真实余量\",\n  },\n  {\n    mode: \"direct\",\n    label: \"直除 Direct\",\n    detail: \"10题 · 准确有效商位与真实乘回余量\",\n  },\n  {\n    mode: \"r\",\n    label: \"求 r\",\n    detail: \"20题 · 百分数精确到0.1个百分点\",\n  },\n  {\n    mode: \"nxr_first\",\n    label: \"N×r · 一阶\",\n    detail: \"20题 · 每步相对误差≤5%\",\n  },\n  {\n    mode: \"nxr_second\",\n    label: \"N×r · 二阶\",\n    detail: \"10题 · 第二步沿用你的一阶答案\",\n  },\n];\n\nconst directFields = [\n  {\n    key: \"firstQuotientDigit\",\n    label: \"首位商\",\n    hint: \"准确的第一位有效商位\",\n  },\n  {\n    key: \"firstDigitProduct\",\n    label: \"首位商 × 除数\",\n    hint: \"你实际算出的乘回结果\",\n  },\n  {\n    key: \"remainderAfterFirstDigit\",\n    label: \"当前真实余量\",\n    hint: \"你实际算出的余量\",\n  },\n  {\n    key: \"secondQuotientDigit\",\n    label: \"第二位商\",\n    hint: \"准确的第二位有效商位\",\n  },\n  {\n    key: \"thirdQuotientDigit\",\n    label: \"第三位商\",\n    hint: \"仅本题要求时填写\",\n  },\n] as const;\n\ntype SplitRow = { percent: string; amount: string; remainder: string };\nconst emptySplitRow = (): SplitRow => ({\n  percent: \"\",\n  amount: \"\",\n  remainder: \"\",\n});\n\nfunction nextSeed(): number {\n  return Math.floor(Math.random() * 4294967296);\n}\n\nfunction attemptValue(attempt: C2PilotSession[\"attempts\"][number]) {\n  if (attempt.response.kind === \"single\") return attempt.response.value + \"%\";\n  if (attempt.response.fields.scalingFinal !== undefined)\n    return String(attempt.response.fields.scalingFinal);\n  if (attempt.response.fields.splitFinalPercent !== undefined)\n    return String(attempt.response.fields.splitFinalPercent) + \"%\";\n  if (attempt.response.fields.firstQuotientDigit !== undefined)\n    return String(attempt.grade.gradingMetrics?.submittedFinal ?? \"未完成\");\n  const first = String(attempt.response.fields.firstCorrection ?? \"\");\n  const second = attempt.response.fields.secondCorrection;\n  return second === undefined ? first : `${first} → ${String(second)}`;\n}\n\nexport function C2PilotTraining() {\n  const [mode, setMode] = useState<C2PilotMode>(\"r\");\n  const [session, setSession] = useState<C2PilotSession | null>(null);\n  const [first, setFirst] = useState(\"\");\n  const [second, setSecond] = useState(\"\");\n  const [direct, setDirect] = useState<Record<string, string>>({});\n  const [splitRows, setSplitRows] = useState<SplitRow[]>([emptySplitRow()]);\n  const [splitFinalPercent, setSplitFinalPercent] = useState(\"\");\n  const [scaling, setScaling] = useState(emptyScalingForm);\n  const [error, setError] = useState(\"\");\n\n  const start = (selected: C2PilotMode) => {\n    try {\n      setSession(createC2PilotSession(selected, nextSeed()));\n      setMode(selected);\n      setFirst(\"\");\n      setSecond(\"\");\n      setDirect({});\n      setSplitRows([emptySplitRow()]);\n      setSplitFinalPercent(\"\");\n      setScaling(emptyScalingForm());\n      setError(\"\");\n    } catch (caught) {\n      setError(caught instanceof Error ? caught.message : \"无法生成题组\");\n    }\n  };\n\n  const submit = (event: FormEvent<HTMLFormElement>) => {\n    event.preventDefault();\n    if (!session) return;\n\n    const response: TrainingResponse =\n      session.mode === \"r\"\n        ? { kind: \"single\", value: first }\n        : session.mode === \"direct\"\n          ? { kind: \"structured\", fields: { ...direct } }\n          : session.mode === \"scaling\"\n            ? { kind: \"structured\", fields: scalingResponseFields(scaling) }\n          : session.mode === \"split\"\n            ? {\n                kind: \"structured\",\n                fields: {\n                  splitCount: splitRows.length,\n                  splitFinalPercent,\n                  ...Object.fromEntries(\n                    splitRows.flatMap((row, index) => [\n                      [`splitPercent${index + 1}`, row.percent],\n                      [`splitAmount${index + 1}`, row.amount],\n                      [`splitRemainder${index + 1}`, row.remainder],\n                    ]),\n                  ),\n                },\n              }\n            : {\n                kind: \"structured\",\n                fields: {\n                  firstCorrection: first,\n                  ...(session.mode === \"nxr_second\"\n                    ? { secondCorrection: second }\n                    : {}),\n                },\n              };\n\n    try {\n      const next = submitC2PilotAnswer(session, response);\n      setSession(next);\n      setFirst(\"\");\n      setSecond(\"\");\n      setDirect({});\n      setSplitRows([emptySplitRow()]);\n      setSplitFinalPercent(\"\");\n      setScaling(emptyScalingForm());\n      setError(\"\");\n    } catch (caught) {\n      setError(\n        session.mode === \"split\" &&\n          caught instanceof Error &&\n          caught.message ===\n            \"Split requires actual signed blocks, amounts, remainders and final percent.\"\n          ? \"请填写实际使用的比例块、对应量、剩余量和最终累计比例，比例块需为支持的带符号百分数。\"\n          : caught instanceof Error\n            ? caught.message\n            : \"答案无法提交\",\n      );\n    }\n  };\n\n  const question =\n    session?.status === \"active\"\n      ? session.questions[session.currentIndex]\n      : undefined;\n  const complete = session?.status === \"completed\";\n  const directDigits = Number(question?.data.c2DirectRequestedDigits) as 2 | 3;\n  const directEstimate =\n    question && session?.mode === \"direct\"\n      ? c2DirectCompose(\n          direct.firstQuotientDigit,\n          direct.secondQuotientDigit,\n          direct.thirdQuotientDigit,\n          Number(question.data.c2DirectFirstPlace),\n          directDigits,\n        )\n      : undefined;\n\n  return (\n    <main className={styles.shell}>\n      <header className={styles.header}>\n        <span className={styles.eyebrow}>数感 · C2 候选训练工作台</span>\n        <h1>除法综合</h1>\n        <p>\n          直除、拆分、补偿放缩、求 r 与 N×r 已进入候选训练；综合工作台尚未完成。\n        </p>\n      </header>\n\n      {!session ? (\n        <section aria-label=\"选择C2支撑专项\" className={styles.panel}>\n          <h2>选择训练</h2>\n          <p className={styles.muted}>\n            进入后直接生成固定题组，无题量、难度或旧混合模式选择。\n          </p>\n          <div className={styles.options}>\n            {options.map((option) => (\n              <button\n                className={styles.option}\n                key={option.mode}\n                onClick={() => start(option.mode)}\n                type=\"button\"\n              >\n                <strong>{option.label}</strong>\n                <span>{option.detail}</span>\n              </button>\n            ))}\n          </div>\n        </section>\n      ) : null}\n\n      {question ? (\n        <section aria-label=\"C2训练作答\" className={styles.panel}>\n          <div className={styles.progress}>\n            <span>\n              {options.find((option) => option.mode === session?.mode)?.label}\n            </span>\n            <span>\n              第 {session!.currentIndex + 1} / {session!.questions.length} 题\n            </span>\n          </div>\n          <progress\n            aria-label=\"训练进度\"\n            max={session!.questions.length}\n            value={session!.currentIndex}\n          />\n          <h2 className={styles.problem}>{question.prompt}</h2>\n          <form onSubmit={submit}>\n            {session?.mode === \"scaling\" ? (\n              <C2ScalingFields state={scaling} onChange={setScaling} />\n            ) : session?.mode === \"split\" ? (\n              <div className={styles.splitWorkspace}>\n                <p className={styles.muted}>\n                  以除数为100%，自行选带符号熟悉比例块，算对应量与新的余量。\n                  算够即可提交；下一块只能由你主动增加。\n                </p>\n                <div className={styles.splitRows}>\n                  {splitRows.map((row, index) => (\n                    <fieldset className={styles.splitBlock} key={index}>\n                      <legend>拆分第 {index + 1} 块</legend>\n                      {(\n                        [\n                          [\"percent\", \"比例\", \"如 +50 或 -5\"],\n                          [\"amount\", \"对应量\", \"自己算出的带符号数量\"],\n                          [\"remainder\", \"剩余量\", \"本块之后的真实余量\"],\n                        ] as const\n                      ).map(([key, label, hint]) => (\n                        <label className={styles.field} key={key}>\n                          <span>{label}</span>\n                          <input\n                            aria-label={`拆分第${index + 1}块${label}`}\n                            autoComplete=\"off\"\n                            inputMode=\"decimal\"\n                            placeholder={hint}\n                            required\n                            type=\"text\"\n                            value={row[key]}\n                            onChange={(event) =>\n                              setSplitRows((previous) =>\n                                previous.map((entry, at) =>\n                                  at === index\n                                    ? { ...entry, [key]: event.target.value }\n                                    : entry,\n                                ),\n                              )\n                            }\n                          />\n                        </label>\n                      ))}\n                    </fieldset>\n                  ))}\n                </div>\n                <div className={styles.splitActions}>\n                  <button\n                    onClick={() =>\n                      setSplitRows((previous) =>\n                        previous.length >= 20\n                          ? previous\n                          : [...previous, emptySplitRow()],\n                      )\n                    }\n                    type=\"button\"\n                  >\n                    增加下一块\n                  </button>\n                  {splitRows.length > 1 ? (\n                    <button\n                      onClick={() =>\n                        setSplitRows((previous) => previous.slice(0, -1))\n                      }\n                      type=\"button\"\n                    >\n                      移除最后一块\n                    </button>\n                  ) : null}\n                </div>\n                <label className={styles.field}>\n                  <span>最终累计比例（%）</span>\n                  <input\n                    aria-label=\"拆分最终累计比例\"\n                    autoComplete=\"off\"\n                    inputMode=\"decimal\"\n                    placeholder=\"填写自己累计的比例，不能自动代算\"\n                    required\n                    type=\"text\"\n                    value={splitFinalPercent}\n                    onChange={(event) =>\n                      setSplitFinalPercent(event.target.value)\n                    }\n                  />\n                </label>\n              </div>\n            ) : session?.mode === \"direct\" ? (\n              <div className={styles.directFields}>\n                <p className={styles.muted}>\n                  本题需准确截取 {directDigits} 位有效商位，不按3%提前停算。\n                  下列乘回与余量只记录你真实填写的计算，不由程序预填。\n                </p>\n                {directFields\n                  .filter(\n                    (field) =>\n                      field.key !== \"thirdQuotientDigit\" || directDigits === 3,\n                  )\n                  .map((field) => (\n                    <label className={styles.field} key={field.key}>\n                      <span>{field.label}</span>\n                      <input\n                        aria-label={field.label}\n                        autoComplete=\"off\"\n                        inputMode=\"decimal\"\n                        onChange={(event) =>\n                          setDirect((previous) => ({\n                            ...previous,\n                            [field.key]: event.target.value,\n                          }))\n                        }\n                        placeholder={field.hint}\n                        required\n                        type=\"text\"\n                        value={direct[field.key] ?? \"\"}\n                      />\n                    </label>\n                  ))}\n                <p aria-live=\"polite\" className={styles.directPreview}>\n                  当前准确商位组合：{directEstimate ?? \"待填写商位\"}\n                </p>\n              </div>\n            ) : (\n              <label className={styles.field}>\n                <span>\n                  {session?.mode === \"r\"\n                    ? \"r（百分数）\"\n                    : \"你实际算出的一阶修正量 C1\"}\n                </span>\n                <div className={styles.inputRow}>\n                  <input\n                    aria-label={\n                      session?.mode === \"r\" ? \"r百分数\" : \"一阶修正量\"\n                    }\n                    autoComplete=\"off\"\n                    autoFocus\n                    inputMode=\"decimal\"\n                    onChange={(event) => setFirst(event.target.value)}\n                    placeholder={\n                      session?.mode === \"r\" ? \"例如 7.3\" : \"填写你算出的数值\"\n                    }\n                    required\n                    type=\"text\"\n                    value={first}\n                  />\n                  {session?.mode === \"r\" ? <span>%</span> : null}\n                </div>\n              </label>\n            )}\n            {session?.mode === \"nxr_second\" ? (\n              <label className={styles.field}>\n                <span>二阶修正量 C2 = |你填写的 C1| × r</span>\n                <input\n                  aria-label=\"二阶修正量\"\n                  autoComplete=\"off\"\n                  inputMode=\"decimal\"\n                  onChange={(event) => setSecond(event.target.value)}\n                  placeholder=\"沿用自己的一阶数值\"\n                  required\n                  type=\"text\"\n                  value={second}\n                />\n              </label>\n            ) : null}\n            <p className={styles.muted}>\n              {session?.mode === \"scaling\"\n                ? \"原始商3%终局与当前真实路径过程独立诊断；未输入步骤不补造。\"\n                : session?.mode === \"split\"\n                  ? \"按原始商误差≤3%判终局；块量、余量、累计矛盾只用于过程复盘。\"\n                : session?.mode === \"direct\"\n                  ? \"准确截位判断与实际乘回、余量一致性分别诊断，不靠近似百分比判分。\"\n                  : session?.mode === \"r\"\n                    ? \"填写百分数而非小数比率，只保留至多一位小数。\"\n                    : \"每步独立按5%检查；二阶只依据你实际输入的C1，不替你补算。\"}\n            </p>\n            {error ? (\n              <p className={styles.error} role=\"alert\">\n                {error}\n              </p>\n            ) : null}\n            <div className={styles.actions}>\n              <button className={styles.primary} type=\"submit\">\n                提交本题\n              </button>\n              <button onClick={() => start(session!.mode)} type=\"button\">\n                重新训练\n              </button>\n            </div>\n          </form>\n        </section>\n      ) : null}\n\n      {complete ? (\n        <section aria-label=\"C2训练结果\" className={styles.panel}>\n          <span className={styles.eyebrow}>本组已完成</span>\n          <h2>\n            答对 {c2PilotScore(session!)} / {session!.questions.length} 题\n          </h2>\n          <p className={styles.muted}>\n            下表只呈现实际提交的答案和数学判分，不推断你未填写的心算过程。\n          </p>\n          <ol className={styles.results}>\n            {session!.attempts.map((attempt, index) => {\n              const questionForAttempt = session!.questions[index];\n              return (\n                <li className={styles.result} key={attempt.questionId}>\n                  <div className={styles.resultHead}>\n                    <strong>\n                      {index + 1}. {questionForAttempt.prompt}\n                    </strong>\n                    <span>{attempt.grade.isCorrect ? \"正确\" : \"需复盘\"}</span>\n                  </div>\n                  <p>你的答案：{attemptValue(attempt)}</p>\n                  <p>\n                    {session!.mode === \"scaling\"\n                      ? `原始商：${Number(questionForAttempt.data.c2ScalingRawA) / Number(questionForAttempt.data.c2ScalingRawB)}`\n                      : session!.mode === \"split\"\n                        ? `原始商：${Number(questionForAttempt.data.c2SplitRawA) / Number(questionForAttempt.data.c2SplitRawB)}`\n                      : session!.mode === \"direct\"\n                        ? `准确商位：${questionForAttempt.answer}`\n                        : session!.mode === \"r\"\n                          ? `标准：${questionForAttempt.answer}%`\n                          : `一阶参照：${Number(questionForAttempt.data.c2ExactC1).toPrecision(5)}`}\n                  </p>\n                  {session!.mode === \"scaling\" ? (\n                    <div className={styles.splitResult}>\n                      <p>终局：{attempt.grade.gradingMetrics?.finalPass ? \"达到3%\" : \"未达到3%\"} · 过程：{attempt.grade.gradingMetrics?.processConsistency === \"consistent\" ? \"算式一致\" : \"需复核\"}</p>\n                      <p>实际路径：{String(attempt.grade.gradingMetrics?.actualPath)} · 自选B0：{String(attempt.grade.gradingMetrics?.actualBaseline)} · 有符号Δ：{String(attempt.grade.gradingMetrics?.actualSignedDelta)}</p>\n                      <p>实际输入：{JSON.stringify(attempt.response.kind === \"structured\" ? attempt.response.fields : {})}</p>\n                      <p>首次足够阶段：{String(attempt.grade.gradingMetrics?.firstSufficientStage)}{attempt.grade.gradingMetrics?.continuedAfterEnough ? \" · 可以更早停止\" : \"\"}</p>\n                    </div>\n                  ) : null}\n                  {session!.mode === \"split\" ? (\n                    <div className={styles.splitResult}>\n                      <p>\n                        终局：\n                        {attempt.grade.gradingMetrics?.finalPass\n                          ? \"达到3%\"\n                          : \"未达到3%\"}\n                        {\" · \"}\n                        过程：\n                        {attempt.grade.gradingMetrics?.processConsistency ===\n                        \"consistent\"\n                          ? \"算式一致\"\n                          : \"需核查\"}\n                      </p>\n                      <p>\n                        已填{\" \"}\n                        {String(\n                          attempt.grade.gradingMetrics?.enteredBlockCount,\n                        )}{\" \"}\n                        块{\" · \"}\n                        首次足够：第\n                        {String(\n                          attempt.grade.gradingMetrics?.firstSufficientStage ||\n                            \"未达标\",\n                        )}\n                        块\n                        {attempt.grade.gradingMetrics?.continuedAfterEnough\n                          ? \" · 可以更早停止\"\n                          : \"\"}\n                      </p>\n                      <p>\n                        块比例：\n                        {JSON.stringify(\n                          attempt.grade.gradingMetrics?.actualPercents,\n                        )}\n                        {\" · \"}\n                        实际对应量：\n                        {JSON.stringify(\n                          attempt.grade.gradingMetrics?.actualAmounts,\n                        )}\n                        {\" · \"}\n                        实际余量：\n                        {JSON.stringify(\n                          attempt.grade.gradingMetrics?.actualRemainders,\n                        )}\n                      </p>\n                    </div>\n                  ) : null}\n                  {session!.mode === \"direct\" ? (\n                    <p>\n                      终局：\n                      {attempt.grade.gradingMetrics?.finalPass\n                        ? \"准确\"\n                        : \"商位有误\"}\n                      {\" · \"}\n                      过程：\n                      {attempt.grade.gradingMetrics?.processConsistency ===\n                      \"consistent\"\n                        ? \"一致\"\n                        : \"需核查\"}\n                    </p>\n                  ) : null}\n                  {session!.mode === \"nxr_second\" ? (\n                    <p>\n                      二阶参照（按你的 C1）：\n                      {Number(\n                        attempt.grade.gradingMetrics?.processExpectedC2,\n                      ).toPrecision(5)}\n                    </p>\n                  ) : null}\n                </li>\n              );\n            })}\n          </ol>\n          <div className={styles.actions}>\n            <button\n              className={styles.primary}\n              onClick={() => start(session!.mode)}\n              type=\"button\"\n            >\n              再练一组\n            </button>\n            <button\n              onClick={() => {\n                setSession(null);\n                setError(\"\");\n              }}\n              type=\"button\"\n            >\n              切换专项\n            </button>\n          </div>\n        </section>\n      ) : null}\n\n      {!question && error ? (\n        <p className={styles.error} role=\"alert\">\n          {error}\n        </p>\n      ) : null}\n      <footer className={styles.footer}>\n        本工作台仅为尚未合并的C2候选：题目为程序生成的训练数字，不冒充真实真题。\n        本轮冻结题组只保存在页面内存；刷新后不可恢复。综合前台、云同步、历史与导出尚待开发验收。\n      </footer>\n    </main>\n  );\n}\n"},{"path":"src/components/C2ScalingFields.tsx","contents":"\"use client\";\n\nimport type { ChangeEvent } from \"react\";\n\nexport type ScalingPath = \"zero\" | \"result\" | \"numerator_r\" | \"numerator_rough\";\nexport type ScalingFormState = {\n  path: ScalingPath;\n  second: boolean;\n  fields: Record<string, string>;\n};\nexport const emptyScalingForm = (): ScalingFormState => ({\n  path: \"zero\", second: false, fields: {},\n});\n\nconst paths: { value: ScalingPath; label: string }[] = [\n  { value: \"zero\", label: \"零阶 · 基准商已经够用\" },\n  { value: \"result\", label: \"修结果 · Q0 与修正量\" },\n  { value: \"numerator_r\", label: \"修分子 · A×r\" },\n  { value: \"numerator_rough\", label: \"修分子 · 粗商×Δ（无需r或Q0）\" },\n];\nconst inputs = [\n  [\"scalingB0\", \"自选基准 B0\", \"你自然选的分母基准\"],\n  [\"scalingDelta\", \"带符号 Δ = B0 − B\", \"例如 +3 或 -4\"],\n  [\"scalingQ0\", \"实际基准商 Q0\", \"自己计算的 A÷B0\"],\n  [\"scalingR\", \"实际近似幅度 r（小数）\", \"例如 0.042\"],\n  [\"scalingRough\", \"自然粗商 q粗\", \"本次使用的粗商\"],\n  [\"scalingC1\", \"一阶带符号修正 C1\", \"正数或负数\"],\n  [\"scalingA1\", \"一阶分子 A1\", \"自己计算的 A+C1\"],\n  [\"scalingQ1\", \"一阶结果 Q1\", \"自己计算的商\"],\n  [\"scalingC2\", \"后续实际修正 C2\", \"数值由你自己决定\"],\n  [\"scalingA2\", \"后续分子 A2\", \"自己计算的 A1+C2\"],\n  [\"scalingQ2\", \"后续结果 Q2\", \"自己计算的商\"],\n  [\"scalingFinal\", \"最终实际商\", \"相对原始商核验3%\"],\n] as const;\n\nfunction visible(path: ScalingPath, second: boolean, key: string) {\n  if ([\"scalingB0\", \"scalingDelta\", \"scalingFinal\"].includes(key)) return true;\n  if (key === \"scalingQ0\") return path === \"zero\" || path === \"result\";\n  if (key === \"scalingR\") return path === \"result\" || path === \"numerator_r\";\n  if (key === \"scalingRough\") return path === \"numerator_rough\";\n  if ([\"scalingC1\", \"scalingQ1\"].includes(key)) return path !== \"zero\";\n  if (key === \"scalingA1\") return path.startsWith(\"numerator_\");\n  if ([\"scalingC2\", \"scalingQ2\"].includes(key)) return path !== \"zero\" && second;\n  if (key === \"scalingA2\") return path.startsWith(\"numerator_\") && second;\n  return false;\n}\n\nexport function scalingResponseFields(state: ScalingFormState) {\n  const fields: Record<string, string> = {\n    scalingPath: state.path,\n    ...state.path === \"zero\" ? {} : { scalingSecond: state.second ? \"yes\" : \"no\" },\n  };\n  for (const [key] of inputs)\n    if (visible(state.path, state.second, key))\n      fields[key] = state.fields[key] ?? \"\";\n  return fields;\n}\n\n/** Never compute learner values. Changing branches clears previously entered\n * values so a hidden stale step cannot masquerade as a real user action.\n */\nexport function C2ScalingFields({\n  state,\n  onChange,\n}: {\n  state: ScalingFormState;\n  onChange: (next: ScalingFormState) => void;\n}) {\n  const changeField = (key: string) => (event: ChangeEvent<HTMLInputElement>) =>\n    onChange({ ...state, fields: { ...state.fields, [key]: event.target.value } });\n\n  return (\n    <div style={{ display: \"grid\", gap: 14 }}>\n      <p>\n        自己选择 B0 和带符号差量；如果基准商对原式已在3%内，可直接零阶提交，\n        绝不强迫多算修正。\n      </p>\n      <fieldset style={{ border: \"1px solid #cad9db\", borderRadius: 12, padding: 12 }}>\n        <legend>本题实际使用的放缩路径</legend>\n        <div style={{ display: \"grid\", gap: 9 }}>\n          {paths.map((path) => (\n            <label key={path.value}>\n              <input\n                checked={state.path === path.value}\n                name=\"scaling-path\"\n                onChange={() =>\n                  onChange({ path: path.value, second: false, fields: {} })\n                }\n                type=\"radio\"\n                value={path.value}\n              />\n              {path.label}\n            </label>\n          ))}\n        </div>\n      </fieldset>\n      {state.path !== \"zero\" ? (\n        <label>\n          <input\n            checked={state.second}\n            onChange={(event) => {\n              const fields = { ...state.fields };\n              delete fields.scalingC2;\n              delete fields.scalingA2;\n              delete fields.scalingQ2;\n              onChange({ ...state, second: event.target.checked, fields });\n            }}\n            type=\"checkbox\"\n          />\n          我还实际进行了下一阶修正\n        </label>\n      ) : null}\n      <div style={{\n        display: \"grid\",\n        gridTemplateColumns: \"repeat(auto-fit, minmax(min(100%, 230px), 1fr))\",\n        gap: 12,\n      }}>\n        {inputs.filter(([key]) => visible(state.path, state.second, key))\n          .map(([key, label, hint]) => (\n            <label key={key} style={{ display: \"grid\", gap: 6, minWidth: 0 }}>\n              <span>{label}</span>\n              <input\n                aria-label={label}\n                autoComplete=\"off\"\n                inputMode=\"decimal\"\n                onChange={changeField(key)}\n                placeholder={hint}\n                required\n                style={{\n                  border: \"1px solid #c7d6dd\", borderRadius: 10,\n                  padding: \"11px 12px\", width: \"100%\", minWidth: 0,\n                  font: \"inherit\", background: \"white\",\n                }}\n                type=\"text\"\n                value={state.fields[key] ?? \"\"}\n              />\n            </label>\n          ))}\n      </div>\n    </div>\n  );\n}\n"},{"path":"src/lib/c2/pilot-session.ts","contents":"import {\n  gradeTrainingResponse,\n  type TrainingGradeResult,\n} from \"../grader-registry\";\nimport type { GenerationContext } from \"../generate\";\nimport type { GeneratedQuestion, TrainingResponse } from \"../types\";\nimport { generateC2RuntimeSet } from \"./runtime\";\nimport { c2ParseDecimal } from \"./decimal\";\nimport { c2DirectCompose } from \"./direct-pilot\";\nimport { c2ParseSplitResponse } from \"./split-pilot\";\nimport { c2ParseScalingResponse } from \"./scaling-pilot\";\n\nexport type C2PilotMode = \"direct\" | \"split\" | \"scaling\" | \"r\" | \"nxr_first\" | \"nxr_second\";\n\nexport type C2PilotAttempt = {\n  questionId: string;\n  response: TrainingResponse;\n  grade: TrainingGradeResult;\n};\n\nexport type C2PilotSession = {\n  id: string;\n  seed: number;\n  mode: C2PilotMode;\n  questions: GeneratedQuestion[];\n  attempts: C2PilotAttempt[];\n  currentIndex: number;\n  status: \"active\" | \"completed\";\n};\n\n/** Reproducible numeric generation without consuming random draws for IDs. */\nexport function c2SeededContext(seed: number): GenerationContext {\n  if (!Number.isSafeInteger(seed) || seed < 0 || seed > 0xffffffff)\n    throw new Error(\"C2 seed must be an unsigned 32-bit integer.\");\n  let state = seed >>> 0;\n  let serial = 0;\n  return {\n    random: () => {\n      state = (state + 0x6d2b79f5) >>> 0;\n      let t = state;\n      t = Math.imul(t ^ (t >>> 15), t | 1);\n      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    },\n    createId: () => `c2-${seed}-${serial++}`,\n  };\n}\n\nfunction launchRequest(mode: C2PilotMode) {\n  if (mode === \"scaling\")\n    return {\n      preset: { mode: \"method\" as const, route: \"scaling\" as const },\n      questionCount: 10,\n    };\n  if (mode === \"split\")\n    return {\n      preset: { mode: \"method\" as const, route: \"split\" as const },\n      questionCount: 10,\n    };\n  if (mode === \"direct\")\n    return {\n      preset: { mode: \"method\" as const, route: \"direct\" as const },\n      questionCount: 10,\n    };\n  if (mode === \"r\")\n    return {\n      preset: { mode: \"support\" as const, support: \"r\" as const },\n      questionCount: 20,\n      // Existing generator categorization is pilot-only, NOT a signed L quota.\n      difficultyBand: \"L2\" as const,\n    };\n  return {\n    preset: {\n      mode: \"support\" as const,\n      support: \"nxr\" as const,\n      variant:\n        mode === \"nxr_first\"\n          ? (\"ordinary\" as const)\n          : (\"second_order\" as const),\n    },\n    questionCount: mode === \"nxr_first\" ? 20 : 10,\n  };\n}\n\nexport function createC2PilotSession(\n  mode: C2PilotMode,\n  seed: number,\n): C2PilotSession {\n  const questions = generateC2RuntimeSet(\n    launchRequest(mode),\n    c2SeededContext(seed),\n  );\n  if (!questions) throw new Error(\"C2 pilot mode is not launchable.\");\n  return {\n    id: `c2-pilot-${seed}-${mode}`,\n    seed,\n    mode,\n    questions,\n    attempts: [],\n    currentIndex: 0,\n    status: \"active\",\n  };\n}\n\nfunction isNumericAnswer(value: unknown): value is string {\n  return typeof value === \"string\" && c2ParseDecimal(value) !== undefined;\n}\n\n/**\n * One atomic submission consumes exactly one frozen question. No answer or\n * process field is inferred; duplicate/late submissions are rejected.\n */\nexport function submitC2PilotAnswer(\n  session: C2PilotSession,\n  response: TrainingResponse,\n): C2PilotSession {\n  if (session.status !== \"active\") throw new Error(\"C2 session has finished.\");\n  const question = session.questions[session.currentIndex];\n  if (!question) throw new Error(\"C2 session has no current question.\");\n\n  if (session.mode === \"r\") {\n    if (response.kind !== \"single\" || !isNumericAnswer(response.value))\n      throw new Error(\"Enter a finite percentage.\");\n    const user = response.value.trim();\n    if (!/^[-+]?\\d+(?:\\.\\d)?$/.test(user))\n      throw new Error(\n        \"r must be entered to at most one decimal place (0.1pp).\",\n      );\n  } else if (session.mode === \"scaling\") {\n    if (!c2ParseScalingResponse(response))\n      throw new Error(\"请填写当前放缩路径真实使用的数值，未使用的步骤请留空。\");\n  } else if (session.mode === \"split\") {\n    if (!c2ParseSplitResponse(response))\n      throw new Error(\n        \"Split requires actual signed blocks, amounts, remainders and final percent.\",\n      );\n  } else if (session.mode === \"direct\") {\n    const fields = response.kind === \"structured\" ? response.fields : {};\n    const digit = (value: unknown, min: number) => {\n      const parsed = c2ParseDecimal(value);\n      return (\n        typeof value === \"string\" &&\n        parsed !== undefined &&\n        Number.isInteger(parsed) &&\n        parsed >= min &&\n        parsed <= 9\n      );\n    };\n    if (!digit(fields.firstQuotientDigit, 1))\n      throw new Error(\"Enter the actual first quotient digit (1–9).\");\n    if (!isNumericAnswer(fields.firstDigitProduct))\n      throw new Error(\"Enter your actual first-digit multiplication.\");\n    if (!isNumericAnswer(fields.remainderAfterFirstDigit))\n      throw new Error(\"Enter your actual remainder.\");\n    if (!digit(fields.secondQuotientDigit, 0))\n      throw new Error(\"Enter the second quotient digit (0–9).\");\n    const requested = Number(question.data.c2DirectRequestedDigits);\n    if (requested === 3 && !digit(fields.thirdQuotientDigit, 0))\n      throw new Error(\"This question requires the third quotient digit.\");\n    if (\n      !c2DirectCompose(\n        fields.firstQuotientDigit,\n        fields.secondQuotientDigit,\n        fields.thirdQuotientDigit,\n        Number(question.data.c2DirectFirstPlace),\n        requested as 2 | 3,\n      )\n    )\n      throw new Error(\"Direct significant digits are incomplete.\");\n  } else {\n    if (\n      response.kind !== \"structured\" ||\n      !isNumericAnswer(response.fields.firstCorrection)\n    )\n      throw new Error(\"Enter your actual first correction.\");\n    if (\n      session.mode === \"nxr_second\" &&\n      !isNumericAnswer(response.fields.secondCorrection)\n    )\n      throw new Error(\"Enter the second correction based on your first.\");\n  }\n\n  const grade = gradeTrainingResponse(question, response);\n  const attempts = [\n    ...session.attempts,\n    { questionId: question.id, response, grade },\n  ];\n  const currentIndex = session.currentIndex + 1;\n  return {\n    ...session,\n    attempts,\n    currentIndex,\n    status: currentIndex === session.questions.length ? \"completed\" : \"active\",\n  };\n}\n\nexport function c2PilotScore(session: C2PilotSession) {\n  return session.attempts.filter((attempt) => attempt.grade.isCorrect).length;\n}\n"},{"path":"src/lib/c2/scaling-pilot.test.ts","contents":"import { describe, it, expect } from \"vitest\";\nimport type { GeneratedQuestion } from \"../types\";\nimport { gradeTrainingResponse } from \"../grader-registry\";\nimport { c2SeededContext, c2PilotScore, createC2PilotSession,\n  submitC2PilotAnswer } from \"./pilot-session\";\nimport { generateC2RuntimeSet } from \"./runtime\";\nimport { c2ParseScalingResponse, generateC2ScalingQuestion } from \"./scaling-pilot\";\n\nfunction response(path: string, fields: Record<string,string> = {}) {\n  return { kind: \"structured\" as const, fields: {\n    scalingPath: path, scalingB0: \"125\", scalingDelta: \"3\",\n    scalingFinal: \"5.28\", ...fields,\n  }};\n}\nfunction question(a=645,b=122) {\n  return { ...generateC2ScalingQuestion(c2SeededContext(1)),\n    data: { c2TaskKind: \"method_scaling\", c2ScalingRawA: a,\n      c2ScalingRawB: b, c2ScalingCoreA: a, c2ScalingCoreB: b } } as GeneratedQuestion;\n}\nconst grade = (q: GeneratedQuestion, r: ReturnType<typeof response>) =>\n  gradeTrainingResponse(q,r);\n\ndescribe(\"C-007 Scaling actual staged process and independent original quotient\", () => {\n  it(\"accepts genuine zero-order result without any unentered correction\", () => {\n    const r=response(\"zero\",{scalingQ0:\"5.16\",scalingFinal:\"5.16\"});\n    const g=grade(question(),r);\n    expect(g.isCorrect).toBe(true);\n    expect(g.gradingMetrics?.enteredStage).toBe(0);\n    expect(g.gradingMetrics?.processConsistency).toBe(\"consistent\");\n    expect(r.fields.scalingR).toBeUndefined();\n    expect(r.fields.scalingC1).toBeUndefined();\n  });\n  it(\"recognizes user-input positive Delta through rough quotient with no r or Q0\", () => {\n    const r=response(\"numerator_rough\", {\n      scalingRough:\"5\",scalingC1:\"15\",scalingA1:\"660\",scalingQ1:\"5.28\",\n    });\n    const g=grade(question(),r);\n    expect(g.isCorrect).toBe(true);\n    expect(g.gradingMetrics?.processConsistency).toBe(\"consistent\");\n    expect(c2ParseScalingResponse(r)?.r).toBeUndefined();\n    expect(c2ParseScalingResponse(r)?.q0).toBeUndefined();\n  });\n  it(\"retains signed negative Delta for repair-result\", () => {\n    const r=response(\"result\", {\n      scalingB0:\"100\",scalingDelta:\"-4\",scalingQ0:\"2\",scalingR:\"0.04\",\n      scalingC1:\"-0.08\",scalingQ1:\"1.92\",scalingFinal:\"1.92\",\n      scalingSecond:\"no\",\n    });\n    expect(grade(question(200,104),r).isCorrect).toBe(true);\n    expect(grade(question(200,104),r).gradingMetrics?.processConsistency).toBe(\"consistent\");\n  });\n  it(\"supports A×r numerator and legitimate positive second-order\", () => {\n    const r=response(\"numerator_r\", {\n      scalingB0:\"100\",scalingDelta:\"-4\",scalingR:\"0.04\",\n      scalingC1:\"-8\",scalingA1:\"192\",scalingQ1:\"1.92\",\n      scalingSecond:\"yes\",scalingC2:\"0.32\",scalingA2:\"192.32\",\n      scalingQ2:\"1.9232\",scalingFinal:\"1.9232\",\n    });\n    const g=grade(question(200,104),r);\n    expect(g.isCorrect).toBe(true);\n    expect(g.gradingMetrics?.processConsistency).toBe(\"consistent\");\n    expect(g.gradingMetrics?.enteredStage).toBe(2);\n  });\n  it(\"does not falsely apply the A×r second-order formula to rough Delta route\", () => {\n    const r=response(\"numerator_rough\",{\n      scalingB0:\"100\",scalingDelta:\"-4\",\n      scalingRough:\"2\",scalingC1:\"-8\",scalingA1:\"192\",scalingQ1:\"1.92\",\n      scalingSecond:\"yes\",scalingC2:\"0.3\",scalingA2:\"192.3\",scalingQ2:\"1.923\",\n      scalingFinal:\"1.923\",\n    });\n    expect(grade(question(200,104),r).gradingMetrics?.processConsistency).toBe(\"consistent\");\n  });\n  it(\"final pass does not launder an incorrect intermediate process\", () => {\n    const r=response(\"numerator_rough\", {\n      scalingRough:\"5\",scalingC1:\"999\",scalingA1:\"660\",scalingQ1:\"5.28\",\n    });\n    const g=grade(question(),r);\n    expect(g.isCorrect).toBe(true);\n    expect(g.gradingMetrics?.processConsistency).toBe(\"review_needed\");\n    expect(r.fields.scalingC1).toBe(\"999\");\n  });\n  it(\"uses ORIGINAL raw quotient, not transformed core, for 3%\", () => {\n    const q=question(600,1000);\n    q.data.c2ScalingCoreA=500;\n    const g=grade(q,response(\"zero\", {\n      scalingB0:\"1000\",scalingDelta:\"0\",scalingQ0:\"0.5\",scalingFinal:\"0.5\",\n    }));\n    expect(g.isCorrect).toBe(false);\n    expect(g.gradingMetrics?.originalQuotient).toBe(0.6);\n    expect(g.relativeError).toBeCloseTo(1/6);\n  });\n  it(\"rejects unentered/foreign/invalid values and disallowed path fields\", () => {\n    const good=response(\"numerator_rough\", {\n      scalingRough:\"5\",scalingC1:\"15\",scalingA1:\"660\",scalingQ1:\"5.28\",\n    });\n    expect(c2ParseScalingResponse(good)).toBeDefined();\n    for(const edits of [{scalingR:\"0.02\"},{scalingQ0:\"5.16\"},\n      {scalingRough:\"NaN\"},{scalingB0:\"0\"},{scalingFinal:\"1e2\"},\n      {scalingC1:\"0x10\"},{scalingSecond:\"yes\"},\n      {scalingDelta:\"\"},{scalingPath:\"unsupported\"}]){\n      expect(c2ParseScalingResponse({kind:\"structured\",fields:{\n        ...good.fields,...edits}})).toBeUndefined();\n    }\n    const zero=response(\"zero\",{scalingQ0:\"5.16\",scalingSecond:\"no\"});\n    expect(c2ParseScalingResponse(zero)).toBeUndefined();\n  });\n  it(\"always freezes ten unique questions for several seeds without a machine L quota\", () => {\n    for(const seed of [0,7,99,2026,4294967295]){\n      const req={preset:{mode:\"method\" as const,route:\"scaling\" as const},\n        questionCount:10};\n      const a=generateC2RuntimeSet(req,c2SeededContext(seed));\n      expect(a).toHaveLength(10);\n      expect(a).toEqual(generateC2RuntimeSet(req,c2SeededContext(seed)));\n      expect(new Set(a?.map(q=>q.prompt)).size).toBe(10);\n      expect(a?.every(q=>q.data.c2TaskKind===\"method_scaling\")).toBe(true);\n      expect(a?.every(q=>q.difficulty?.tags.includes(\"pilot_unclassified\"))).toBe(true);\n      for(const count of [6,8,12,20])\n        expect(generateC2RuntimeSet({preset:req.preset,questionCount:count},\n          c2SeededContext(seed))).toBeUndefined();\n    }\n  });\n  it(\"completes all ten zero-stage sessions and rejects malformed submission atomically\", () => {\n    let session=createC2PilotSession(\"scaling\",75);\n    expect(session.questions).toHaveLength(10);\n    const first=session.questions[0];\n    expect(()=>submitC2PilotAnswer(session,response(\"zero\",{\n      scalingB0:\"0\",scalingDelta:\"1\",scalingQ0:\"1\",\n    }))).toThrow();\n    expect(session.currentIndex).toBe(0);\n    expect(session.questions[0]).toBe(first);\n    for(const q of session.questions) {\n      const a=Number(q.data.c2ScalingCoreA),b=Number(q.data.c2ScalingCoreB);\n      // A self-chosen non-identical baseline with a sufficiently close quotient.\n      const b0=b+1;\n      session=submitC2PilotAnswer(session,response(\"zero\",{\n        scalingB0:String(b0),scalingDelta:\"1\",\n        scalingQ0:String(a/b0),scalingFinal:String(a/b0),\n      }));\n    }\n    expect(session.status).toBe(\"completed\");\n    expect(session.attempts).toHaveLength(10);\n    expect(c2PilotScore(session)).toBe(10);\n    expect(()=>submitC2PilotAnswer(session,response(\"zero\"))).toThrow(/finished/);\n    expect(createC2PilotSession(\"scaling\",76).questions).not.toEqual(session.questions);\n  });\n});\n"},{"path":"src/lib/c2/scaling-pilot.ts","contents":"import {\n  registerCustomCGrader,\n  type TrainingGradeResult,\n} from \"../grader-registry\";\nimport type { GenerationContext } from \"../generate\";\nimport { productionGenerationContext } from \"../generate\";\nimport type { GeneratedQuestion, TrainingResponse } from \"../types\";\nimport { encodeC2Preset } from \"./contract\";\nimport { c2ParseDecimal } from \"./decimal\";\nimport { c2FormatNumber, c2PassesTarget, c2RelativeError, c2Round } from \"./math\";\n\nexport const C2_SCALING_GRADER_ID = \"c2-scaling-real-process-v1\";\nexport const C2_SCALING_GENERATION_VERSION = \"c2-scaling-pilot-v1\";\nexport type C2ScalingPath = \"zero\" | \"result\" | \"numerator_r\" | \"numerator_rough\";\nexport type C2ScalingSubmission = {\n  path: C2ScalingPath;\n  b0: number;\n  delta: number;\n  final: number;\n  q0?: number;\n  r?: number;\n  rough?: number;\n  c1?: number;\n  a1?: number;\n  q1?: number;\n  c2?: number;\n  a2?: number;\n  q2?: number;\n};\nconst paths: C2ScalingPath[] = [\"zero\", \"result\", \"numerator_r\", \"numerator_rough\"];\nconst names: Record<keyof Omit<C2ScalingSubmission, \"path\">, string> = {\n  b0: \"scalingB0\", delta: \"scalingDelta\", final: \"scalingFinal\",\n  q0: \"scalingQ0\", r: \"scalingR\", rough: \"scalingRough\",\n  c1: \"scalingC1\", a1: \"scalingA1\", q1: \"scalingQ1\",\n  c2: \"scalingC2\", a2: \"scalingA2\", q2: \"scalingQ2\",\n};\n\n/** Only explicitly entered numeric fields are accepted. Unknown or\n * out-of-path fields are rejected, not silently inferred as user work.\n * r is a non-negative ratio (not a percentage) when actually used.\n */\nexport function c2ParseScalingResponse(\n  response: TrainingResponse,\n): C2ScalingSubmission | undefined {\n  if (response.kind !== \"structured\") return undefined;\n  const f = response.fields;\n  if (typeof f.scalingPath !== \"string\" ||\n    !paths.includes(f.scalingPath as C2ScalingPath)) return undefined;\n  const path = f.scalingPath as C2ScalingPath;\n  const second = f.scalingSecond === \"yes\";\n  if (f.scalingSecond !== undefined &&\n    f.scalingSecond !== \"yes\" && f.scalingSecond !== \"no\") return undefined;\n  if (path === \"zero\" && f.scalingSecond !== undefined) return undefined;\n  const required: (keyof typeof names)[] = [\"b0\", \"delta\", \"final\"];\n  if (path === \"zero\" || path === \"result\") required.push(\"q0\");\n  if (path === \"result\" || path === \"numerator_r\") required.push(\"r\");\n  if (path === \"numerator_rough\") required.push(\"rough\");\n  if (path !== \"zero\") {\n    required.push(\"c1\", \"q1\");\n    if (path !== \"result\") required.push(\"a1\");\n  }\n  if (second) {\n    required.push(\"c2\", \"q2\");\n    if (path !== \"result\") required.push(\"a2\");\n  }\n  const parsed: Record<string, number> = {};\n  for (const [key, field] of Object.entries(names)) {\n    if (!required.includes(key as keyof typeof names)) {\n      if (f[field] !== undefined) return undefined;\n      continue;\n    }\n    const value = c2ParseDecimal(f[field]);\n    if (value === undefined) return undefined;\n    parsed[key] = value;\n  }\n  if (parsed.b0 <= 0 || (parsed.r !== undefined && parsed.r < 0) ||\n    (parsed.rough !== undefined && parsed.rough <= 0) ||\n    (parsed.c2 !== undefined && path !== \"numerator_rough\" && parsed.c2 < 0))\n    return undefined;\n  if (Object.keys(f).some(k => ![\"scalingPath\", \"scalingSecond\", ...Object.values(names)].includes(k)))\n    return undefined;\n  return { path, ...parsed } as C2ScalingSubmission;\n}\n\n/** One candidate arithmetic shape, no machine L, path quota or oracle route.\n * Learners select B0 themselves. The generated expression is not a teacher's\n * question; raw and core coincide only in this pilot.\n */\nexport function generateC2ScalingQuestion(\n  context: GenerationContext = productionGenerationContext,\n): GeneratedQuestion {\n  const b = Math.floor(context.random() * 231) + 120;\n  const ratio = 0.2 + context.random() * 4.6;\n  const a = Math.max(1, Math.round(b * ratio));\n  return {\n    id: context.createId(),\n    type: \"c_training\",\n    subtype: \"c_task\",\n    prompt: `${a} ÷ ${b}`,\n    answer: c2FormatNumber(a / b),\n    data: {\n      c2TaskKind: \"method_scaling\",\n      c2ScalingRawA: a, c2ScalingRawB: b,\n      c2ScalingCoreA: a, c2ScalingCoreB: b,\n    },\n    difficulty: { level: 1, tags: [\"C2\", \"scaling\", \"pilot_unclassified\"] },\n    primaryStructure: \"c2_scaling_real_process\",\n    secondaryTags: [\"candidate_unclassified\"],\n    generationRuleVersion: C2_SCALING_GENERATION_VERSION,\n    inputKind: \"structured\",\n    targetPrecision: \"3%\",\n    cMeta: {\n      project: \"C2\", mode: \"method\",\n      preset: encodeC2Preset({ mode: \"method\", route: \"scaling\" }),\n      grading: { kind: \"custom\", graderId: C2_SCALING_GRADER_ID,\n        version: C2_SCALING_GRADER_ID },\n    },\n  };\n}\n\nfunction gradeC2Scaling(\n  question: GeneratedQuestion,\n  response: TrainingResponse,\n): TrainingGradeResult {\n  const user = c2ParseScalingResponse(response);\n  const a = Number(question.data.c2ScalingCoreA);\n  const b = Number(question.data.c2ScalingCoreB);\n  const rawA = Number(question.data.c2ScalingRawA);\n  const rawB = Number(question.data.c2ScalingRawB);\n  if (!user || ![a,b,rawA,rawB].every(v => Number.isFinite(v) && v > 0))\n    return { isCorrect: false, accuracyLevel: \"wrong\", gradingMetrics:\n      { gradingVersion: C2_SCALING_GRADER_ID, invalidResponse: true } };\n\n  const exact = rawA / rawB;\n  const finalPass = c2PassesTarget(user.final, exact);\n  const eq = (left: number, right: number) => c2Round(left, 6) === c2Round(right, 6);\n  const checks: boolean[] = [eq(user.delta, user.b0 - b)];\n  if (user.q0 !== undefined) checks.push(eq(user.q0, a / user.b0));\n  if (user.path === \"zero\") checks.push(eq(user.final, user.q0!));\n  if (user.path === \"result\") {\n    checks.push(eq(user.c1!, Math.sign(user.delta) * user.q0! * user.r!));\n    checks.push(eq(user.q1!, user.q0! + user.c1!));\n    if (user.c2 !== undefined) {\n      checks.push(eq(user.c2, user.q0! * user.r! * user.r!));\n      checks.push(eq(user.q2!, user.q1! + user.c2));\n    }\n  } else if (user.path !== \"zero\") {\n    const expectedC1 = user.path === \"numerator_r\"\n      ? Math.sign(user.delta) * a * user.r!\n      : user.rough! * user.delta;\n    checks.push(eq(user.c1!, expectedC1));\n    checks.push(eq(user.a1!, a + user.c1!));\n    checks.push(eq(user.q1!, user.a1! / user.b0));\n    if (user.c2 !== undefined) {\n      if (user.path === \"numerator_r\")\n        checks.push(eq(user.c2, a * user.r! * user.r!));\n      // A rough-quotient path has no invented standard C2 formula:\n      // only its explicitly entered add-to-numerator identity is audited.\n      checks.push(eq(user.a2!, user.a1! + user.c2));\n      checks.push(eq(user.q2!, user.a2! / user.b0));\n    }\n  }\n  if (user.path !== \"zero\") checks.push(eq(user.final, user.q2 ?? user.q1!));\n  const finalStage = user.c2 === undefined ? (user.path === \"zero\" ? 0 : 1) : 2;\n  const initialSufficient = user.q0 !== undefined && c2PassesTarget(user.q0, exact);\n  const oneSufficient = user.q1 !== undefined && c2PassesTarget(user.q1, exact);\n  const firstSufficientStage = initialSufficient ? 0 : oneSufficient ? 1 :\n    finalPass ? finalStage : -1;\n  return {\n    isCorrect: finalPass,\n    accuracyLevel: finalPass ? \"accepted\" : \"wrong\",\n    relativeError: c2RelativeError(user.final, exact),\n    gradingMetrics: {\n      gradingVersion: C2_SCALING_GRADER_ID,\n      finalPass,\n      processConsistency: checks.every(Boolean) ? \"consistent\" : \"review_needed\",\n      processChecks: checks.map((ok) => ok ? \"ok\" : \"review\"),\n      actualPath: user.path,\n      actualBaseline: user.b0, actualSignedDelta: user.delta,\n      actualFinal: user.final, originalQuotient: exact,\n      enteredStage: finalStage, firstSufficientStage,\n      continuedAfterEnough: firstSufficientStage >= 0 &&\n        finalStage > firstSufficientStage,\n    },\n  };\n}\nregisterCustomCGrader(C2_SCALING_GRADER_ID, gradeC2Scaling);\n"}];

it("C007 temporary formatter truth from protected CI runner", async () => {
  for (const [index, item] of cases.entries()) {
    const formatted = await prettier.format(item.contents, {
      ...(await prettier.resolveConfig(item.path)),
      filepath: item.path,
    });
    console.log("C007_FMT_" + index + ":" + Buffer.from(formatted, "utf8").toString("base64"));
  }
}, 120000);
